-- ✅ ตรวจผล: กี่ตัวได้รูป / กี่รุ่นได้โบรชัวร์ / เหลือตัวไหนยังไม่มีรูป
select count(*) filter (where photo_url is not null and photo_url <> '') as มีรูปแล้ว,
       count(*) filter (where photo_url is null or photo_url = '') as ยังไม่มีรูป
from materials where kind = 'ac';
select count(*) filter (where brochure_url is not null) as มีโบรชัวร์, count(*) as รุ่นทั้งหมด from ac_series;
select coalesce(brand,'?') as ยี่ห้อ, series as รุ่น, count(*) as จำนวน
from materials where kind = 'ac' and (photo_url is null or photo_url = '')
group by 1, 2 order by 1, 2;
